def semver_sort(versions):
    def parse_key(v):
        core = v.split('+', 1)[0]
        if '-' in core:
            main, pre = core.split('-', 1)
        else:
            main, pre = core, None
        major, minor, patch = (int(x) for x in main.split('.'))
        if pre is None:
            has_pre = 0
            pre_ids = ()
        else:
            has_pre = 1
            ids = pre.split('.')
            pre_ids = tuple(
                (0, int(i)) if i.isdigit() else (1, i)
                for i in ids
            )
        return (major, minor, patch, has_pre, pre_ids)

    return sorted(versions, key=parse_key)

